import{_ as i,o as a,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Bare Metal Cloud Monitoring Feature Guide","description":"","frontmatter":{"title":"Bare Metal Cloud Monitoring Feature Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-monitoring-feature-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-monitoring-feature-guide.md","lastUpdated":1794292919000}'),o={name:"operations-knowledge-base/baremetal/bare-metal-cloud-monitoring-feature-guide.md"};function s(n,e,l,d,u,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document explains how to use the monitoring feature in the Bare Metal Cloud Control Panel, including monitoring metrics, historical data viewing, and frequently asked questions. It helps you monitor your server&#39;s resource usage in real time and assists with daily operations and troubleshooting.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-monitoring-feature-overview" tabindex="-1">1. Monitoring Feature Overview <a class="header-anchor" href="#_1-monitoring-feature-overview" aria-label="Permalink to &quot;1. Monitoring Feature Overview&quot;">​</a></h2><p>The Bare Metal Cloud Control Panel provides built-in monitoring to help you view your server&#39;s resource usage and historical performance trends.</p><p>The monitoring page allows you to quickly understand the current operating status of your server and analyze historical resource usage for performance optimization and troubleshooting.</p><p>The following monitoring metrics are currently available:</p><ul><li>CPU Usage</li><li>Memory Usage</li><li>Disk I/O</li><li>Network Traffic</li><li>Resource Usage Charts</li></ul><p>You can also view historical monitoring data by selecting a specific date and time range.</p><hr><h2 id="_2-how-to-view-monitoring-information" tabindex="-1">2. How to View Monitoring Information <a class="header-anchor" href="#_2-how-to-view-monitoring-information" aria-label="Permalink to &quot;2. How to View Monitoring Information&quot;">​</a></h2><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Select the server you want to monitor.</li><li>Open the <strong>Management</strong> page.</li><li>Click <strong>Monitor</strong>.</li></ol><p>The monitoring page will display the server&#39;s resource usage and performance statistics.</p><hr><h2 id="_3-monitoring-metrics" tabindex="-1">3. Monitoring Metrics <a class="header-anchor" href="#_3-monitoring-metrics" aria-label="Permalink to &quot;3. Monitoring Metrics&quot;">​</a></h2><h2 id="cpu-usage" tabindex="-1">CPU Usage <a class="header-anchor" href="#cpu-usage" aria-label="Permalink to &quot;CPU Usage&quot;">​</a></h2><p>CPU Usage indicates how much processor resource is currently being utilized.</p><p>Consistently high CPU usage may indicate:</p><ul><li>High server workload</li><li>CPU-intensive applications</li><li>Abnormal or resource-consuming processes</li></ul><hr><h2 id="memory-usage" tabindex="-1">Memory Usage <a class="header-anchor" href="#memory-usage" aria-label="Permalink to &quot;Memory Usage&quot;">​</a></h2><p>Memory Usage shows the amount of system memory currently in use.</p><p>If memory usage remains close to full capacity for an extended period, it may result in:</p><ul><li>Slow system performance</li><li>Reduced application responsiveness</li><li>Service interruptions</li></ul><p>If necessary, consider optimizing applications or upgrading server resources.</p><hr><h2 id="disk-i-o" tabindex="-1">Disk I/O <a class="header-anchor" href="#disk-i-o" aria-label="Permalink to &quot;Disk I/O&quot;">​</a></h2><p>Disk I/O reflects the server&#39;s disk read and write activity.</p><p>Consistently high Disk I/O may indicate:</p><ul><li>Heavy file read/write operations</li><li>Frequent database activity</li><li>Backup or synchronization tasks</li><li>High disk workload</li></ul><hr><h2 id="network-traffic" tabindex="-1">Network Traffic <a class="header-anchor" href="#network-traffic" aria-label="Permalink to &quot;Network Traffic&quot;">​</a></h2><p>Network Traffic displays the amount of data transmitted through the server&#39;s network interface.</p><p>It can be used to monitor:</p><ul><li>Network traffic trends</li><li>Business traffic patterns</li><li>Upload and download activity</li></ul><p>If network traffic increases significantly within a short period, it is recommended to verify whether the activity is expected.</p><hr><h2 id="resource-usage-charts" tabindex="-1">Resource Usage Charts <a class="header-anchor" href="#resource-usage-charts" aria-label="Permalink to &quot;Resource Usage Charts&quot;">​</a></h2><p>The monitoring page provides graphical charts showing historical resource usage over time.</p><p>You can select different dates and time ranges to review historical monitoring data, making it easier to analyze performance trends and identify when issues occurred.</p><hr><h2 id="_4-how-to-identify-potential-issues" tabindex="-1">4. How to Identify Potential Issues <a class="header-anchor" href="#_4-how-to-identify-potential-issues" aria-label="Permalink to &quot;4. How to Identify Potential Issues&quot;">​</a></h2><p>Monitoring data can help you quickly determine whether your server is experiencing abnormal resource usage.</p><p>Common examples include:</p><blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Monitoring Observation</td><td>Possible Cause</td></tr><tr><td>CPU usage remains consistently high</td><td>High workload, resource-intensive applications, or abnormal processes</td></tr><tr><td>Memory usage stays close to full capacity</td><td>Insufficient memory, high application usage, or memory leaks</td></tr><tr><td>Disk I/O remains consistently high</td><td>Heavy disk operations, frequent database activity, or backup tasks</td></tr><tr><td>Sudden increase in network traffic</td><td>Increased business traffic, file transfers, data synchronization, or abnormal network activity</td></tr><tr><td>Resource usage remains significantly higher than usual</td><td>Further investigation using system logs and application status is recommended</td></tr></tbody></table><p><strong>Note:</strong></p><p>Monitoring data reflects the server&#39;s resource usage only. Determining the root cause of an issue may require reviewing system logs, application status, and server configuration.</p></blockquote><hr><h2 id="_5-viewing-historical-monitoring-data" tabindex="-1">5. Viewing Historical Monitoring Data <a class="header-anchor" href="#_5-viewing-historical-monitoring-data" aria-label="Permalink to &quot;5. Viewing Historical Monitoring Data&quot;">​</a></h2><p>The monitoring feature allows you to review historical resource usage.</p><p>You can select a specific date and time range to view server performance during a particular period.</p><p>Historical monitoring data can be used to:</p><ul><li>Analyze server performance trends</li><li>Identify when an issue occurred</li><li>Compare resource usage over time</li><li>Assist in troubleshooting performance-related problems</li></ul><hr><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-is-the-monitoring-data-updated-in-real-time" tabindex="-1">Q1: Is the monitoring data updated in real time? <a class="header-anchor" href="#q1-is-the-monitoring-data-updated-in-real-time" aria-label="Permalink to &quot;Q1: Is the monitoring data updated in real time?&quot;">​</a></h3><p>Monitoring data is collected at regular intervals, so a short delay may occur before the latest information is displayed.</p><hr><h3 id="q2-does-high-cpu-usage-indicate-a-server-failure" tabindex="-1">Q2: Does high CPU usage indicate a server failure? <a class="header-anchor" href="#q2-does-high-cpu-usage-indicate-a-server-failure" aria-label="Permalink to &quot;Q2: Does high CPU usage indicate a server failure?&quot;">​</a></h3><p>Not necessarily.</p><p>High CPU usage may simply indicate increased business traffic, running applications, or scheduled system tasks.</p><p>It is recommended to analyze CPU usage together with system processes and application activity.</p><hr><h3 id="q3-why-has-my-network-traffic-suddenly-increased" tabindex="-1">Q3: Why has my network traffic suddenly increased? <a class="header-anchor" href="#q3-why-has-my-network-traffic-suddenly-increased" aria-label="Permalink to &quot;Q3: Why has my network traffic suddenly increased?&quot;">​</a></h3><p>Possible reasons include:</p><ul><li>Increased website traffic</li><li>File uploads or downloads</li><li>Data synchronization</li><li>Software updates</li><li>Abnormal network activity</li></ul><p>Please review your server logs and running services to determine the cause.</p><hr><h3 id="q4-the-monitoring-data-looks-normal-but-my-server-is-still-inaccessible-what-should-i-do" tabindex="-1">Q4: The monitoring data looks normal, but my server is still inaccessible. What should I do? <a class="header-anchor" href="#q4-the-monitoring-data-looks-normal-but-my-server-is-still-inaccessible-what-should-i-do" aria-label="Permalink to &quot;Q4: The monitoring data looks normal, but my server is still inaccessible. What should I do?&quot;">​</a></h3><p>Monitoring data reflects only the server&#39;s resource usage.</p><p>If the server cannot be accessed, please also check:</p><ul><li>Network connectivity</li><li>Security Group rules</li><li>Firewall configuration</li><li>SSH or Remote Desktop (RDP) services</li><li>Application status</li></ul><p>If necessary, use the <strong>VNC Console</strong> or <strong>Rescue Mode</strong> for further troubleshooting.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Monitoring data is intended to provide an overview of server resource usage and should not be used as the sole indicator of server health.</p><p>⚠️ It is recommended to regularly monitor CPU, Memory, Disk I/O, and Network Traffic to identify potential issues early.</p><p>⚠️ Historical monitoring data can be viewed by selecting a specific date and time range, making it easier to analyze resource usage trends and troubleshoot problems.</p><p>⚠️ If server resources remain under heavy load for an extended period, consider optimizing your applications or upgrading your server configuration.</p><hr>',79)])])}const g=i(o,[["render",s]]);export{p as __pageData,g as default};
